pub struct OperationBuilder<'a: 'b, 'b, A: flatbuffers::Allocator + 'a> {
    fbb_: &'b mut flatbuffers::FlatBufferBuilder<'a, A>,
    start_: flatbuffers::WIPOffset<flatbuffers::TableUnfinishedWIPOffset>,
}
impl<'a: 'b, 'b, A: flatbuffers::Allocator + 'a> OperationBuilder<'a, 'b, A> {
    #[inline]
    pub fn add_ui_type(&mut self, ui_type: UiOperation) {
        self.fbb_
            .push_slot::<UiOperation>(Operation::VT_UI_TYPE, ui_type, UiOperation::NONE);
    }
    #[inline]
    pub fn add_ui(&mut self, ui: flatbuffers::WIPOffset<flatbuffers::UnionWIPOffset>) {
        self.fbb_
            .push_slot_always::<flatbuffers::WIPOffset<_>>(Operation::VT_UI, ui);
    }
    #[inline]
    pub fn add_web_type(&mut self, web_type: WebOperation) {
        self.fbb_
            .push_slot::<WebOperation>(Operation::VT_WEB_TYPE, web_type, WebOperation::NONE);
    }
    #[inline]
    pub fn add_web(&mut self, web: flatbuffers::WIPOffset<flatbuffers::UnionWIPOffset>) {
        self.fbb_
            .push_slot_always::<flatbuffers::WIPOffset<_>>(Operation::VT_WEB, web);
    }
    #[inline]
    pub fn add_mobile_type(&mut self, mobile_type: MobileOperation) {
        self.fbb_.push_slot::<MobileOperation>(
            Operation::VT_MOBILE_TYPE,
            mobile_type,
            MobileOperation::NONE,
        );
    }
    #[inline]
    pub fn add_mobile(&mut self, mobile: flatbuffers::WIPOffset<flatbuffers::UnionWIPOffset>) {
        self.fbb_
            .push_slot_always::<flatbuffers::WIPOffset<_>>(Operation::VT_MOBILE, mobile);
    }
    #[inline]
    pub fn add_columnar(&mut self, columnar: flatbuffers::WIPOffset<ColumnarBatch<'b>>) {
        self.fbb_
            .push_slot_always::<flatbuffers::WIPOffset<ColumnarBatch>>(
                Operation::VT_COLUMNAR,
                columnar,
            );
    }
    #[inline]
    pub fn new(_fbb: &'b mut flatbuffers::FlatBufferBuilder<'a, A>) -> OperationBuilder<'a, 'b, A> {
        let start = _fbb.start_table();
        OperationBuilder {
            fbb_: _fbb,
            start_: start,
        }
    }
    #[inline]
    pub fn finish(self) -> flatbuffers::WIPOffset<Operation<'a>> {
        let o = self.fbb_.end_table(self.start_);
        flatbuffers::WIPOffset::new(o.value())
    }
}

