#[derive(Debug, Clone, PartialEq)]
pub struct OperationT {
    pub ui: UiOperationT,
    pub web: WebOperationT,
    pub mobile: MobileOperationT,
    pub columnar: Option<Box<ColumnarBatchT>>,
}
impl Default for OperationT {
    fn default() -> Self {
        Self {
            ui: UiOperationT::NONE,
            web: WebOperationT::NONE,
            mobile: MobileOperationT::NONE,
            columnar: None,
        }
    }
}
impl OperationT {
    pub fn pack<'b, A: flatbuffers::Allocator + 'b>(
        &self,
        _fbb: &mut flatbuffers::FlatBufferBuilder<'b, A>,
    ) -> flatbuffers::WIPOffset<Operation<'b>> {
        let ui_type = self.ui.ui_operation_type();
        let ui = self.ui.pack(_fbb);
        let web_type = self.web.web_operation_type();
        let web = self.web.pack(_fbb);
        let mobile_type = self.mobile.mobile_operation_type();
        let mobile = self.mobile.pack(_fbb);
        let columnar = self.columnar.as_ref().map(|x| x.pack(_fbb));
        Operation::create(
            _fbb,
            &OperationArgs {
                ui_type,
                ui,
                web_type,
                web,
                mobile_type,
                mobile,
                columnar,
            },
        )
    }
}
